#include "modbus_rtu.h"
#include "command_panel.h"
#include <charconv>
#include <cmath>
#include <set>
#include <algorithm>
namespace {
size_t width(const std::string& type){return type=="u16"||type=="i16"?2:type=="u32"||type=="i32"||type=="f32"?4:type=="f64"?8:0;}
bool scalar(std::string_view s,double& out){const auto r=std::from_chars(s.data(),s.data()+s.size(),out);return r.ec==std::errc{}&&r.ptr==s.data()+s.size()&&std::isfinite(out);}
std::string crc(std::string data){const auto value=frame_checksum(data,FrameChecksum::Modbus16);data.push_back(static_cast<char>(value));data.push_back(static_cast<char>(value>>8));return data;}
bool crc_ok(std::string_view bytes){return bytes.size()>=3&&frame_checksum(bytes.substr(0,bytes.size()-2),FrameChecksum::Modbus16)==static_cast<uint32_t>(static_cast<unsigned char>(bytes[bytes.size()-2])|(static_cast<unsigned char>(bytes.back())<<8));}
}
bool parse_rtu_fields(std::string_view text,std::vector<RtuField>& fields,std::string& error){std::vector<std::vector<std::string>> rows;if(!uart_csv_rows(text,rows,error))return false;std::vector<RtuField> next;for(const auto& row:rows){if(row.size()<3||row.size()>6){error="Fields: name,word_offset,type[,ABCD/CDAB/BADC/DCBA[,scale[,add]]].";return false;}RtuField field;field.name=row[0];field.type=row[2];double offset=0;if(!scalar(row[1],offset)||offset<0||offset>124||offset!=std::floor(offset)){error="Register offset must be an integer 0..124.";return false;}field.reg=static_cast<size_t>(offset);if(row.size()>3)field.order=row[3];if((row.size()>4&&!scalar(row[4],field.scale))||(row.size()>5&&!scalar(row[5],field.add))){error="Scale/add must be finite.";return false;}next.push_back(std::move(field));}fields=std::move(next);return true;}
bool validate_rtu(const RtuConfig& c,std::string& error){if(c.unit<1||c.unit>247||(c.function!=3&&c.function!=4)||c.address>65535||c.count<1||c.count>125||c.address+c.count>65536||c.period_ms<100||c.period_ms>60000||c.timeout_ms<100||c.timeout_ms>60000||c.idle_ms<2||c.idle_ms>1000||c.fields.size()>64){error="Unit 1..247; function 03/04; zero-based address 0..65535; count 1..125; interval/timeout 100..60000 ms; max 64 fields.";return false;}
    std::set<std::string> names;for(const auto& f:c.fields){std::vector<BinaryField> check;std::string detail;if(!width(f.type)||f.reg+width(f.type)/2>c.count||(f.order!="ABCD"&&f.order!="CDAB"&&f.order!="BADC"&&f.order!="DCBA")||!std::isfinite(f.scale)||!std::isfinite(f.add)||!names.insert(f.name).second||!parse_binary_fields(f.name+",0,"+f.type+"be",check,detail)){error="Invalid/duplicate RTU field, type, order or register range.";return false;}}return true;}
std::string rtu_request(const RtuConfig& c){std::string out;out.push_back(static_cast<char>(c.unit));out.push_back(static_cast<char>(c.function));out.push_back(static_cast<char>(c.address>>8));out.push_back(static_cast<char>(c.address));out.push_back(static_cast<char>(c.count>>8));out.push_back(static_cast<char>(c.count));return crc(std::move(out));}
bool RtuPoller::start(RtuConfig config,uint64_t generation,uint64_t now,std::string& error){if(active_){error="Stop the current poller first.";return false;}if(!validate_rtu(config,error))return false;config_=std::move(config);generation_=generation;due_=now+config_.idle_ms;last_rx_=now;waiting_=sending_=false;active_=true;pending_.clear();result_.reset();errors_=0;status_="Polling ready; FC03/04 read-only";return true;}
bool RtuPoller::next(uint64_t now,std::string& bytes){tick(now);if(!active_||waiting_||sending_||now<due_||now-last_rx_<config_.idle_ms)return false;pending_.clear();bytes=rtu_request(config_);sending_=true;status_="RTU request pending";return true;}
void RtuPoller::complete(bool ok,uint64_t now){if(!active_||!sending_)return;sending_=false;if(!ok){stop("STOPPED: RTU write failed/partial; no retry");return;}waiting_=true;deadline_=now+config_.timeout_ms;status_="RTU waiting for matching CRC response";parse(now);}
void RtuPoller::receive(std::string_view bytes,uint64_t now,double seconds){last_rx_=now;seconds_=seconds;tick(now);if(!active_||(!sending_&&!waiting_))return;if(bytes.size()>512||pending_.size()+bytes.size()>512){stop("STOPPED: RTU response exceeds bounded buffer");return;}pending_.append(bytes);if(waiting_)parse(now);}
void RtuPoller::parse(uint64_t now){size_t at=0;while(waiting_&&at+3<=pending_.size()){const auto unit=static_cast<unsigned char>(pending_[at]),function=static_cast<unsigned char>(pending_[at+1]),count=static_cast<unsigned char>(pending_[at+2]);if(unit!=config_.unit||(function!=config_.function&&function!=(config_.function|128))){++at;continue;}const size_t length=function&128?5:static_cast<size_t>(count)+5;if(!(function&128)&&(count!=config_.count*2)){++at;++errors_;continue;}if(pending_.size()-at<length)break;const auto frame=std::string_view(pending_).substr(at,length);if(!crc_ok(frame)){++at;++errors_;continue;}if(function&128){stop("Modbus exception "+std::to_string(count)+"; polling stopped");return;}RtuResult out;out.seconds=seconds_;const auto data=frame.substr(3,count);for(size_t n=0;n<data.size();n+=2)out.registers.push_back((static_cast<unsigned char>(data[n])<<8)|static_cast<unsigned char>(data[n+1]));
        for(const auto& f:config_.fields){const auto n=width(f.type);std::string ordered(data.substr(f.reg*2,n));if(f.order=="CDAB"||f.order=="DCBA"){for(size_t i=0;i<n/2;++i)if(i<n/2-1-i){std::swap(ordered[i*2],ordered[(n/2-1-i)*2]);std::swap(ordered[i*2+1],ordered[(n/2-1-i)*2+1]);}}if(f.order=="BADC"||f.order=="DCBA")for(size_t i=0;i<n;i+=2)std::swap(ordered[i],ordered[i+1]);BinaryFrameConfig config;config.fixed_bytes=n;config.fields={{f.name,f.type+"be",0,f.scale,f.add}};BinaryFrameDecoder decoder;std::string error;decoder.configure(config,error);const auto frames=decoder.feed(ordered,0,seconds_);if(!frames.empty())for(const auto& v:frames.front().values)out.values.push_back(v);}
        out.bytes=std::string(frame);result_=std::move(out);waiting_=false;due_=now+config_.period_ms;status_="RTU response OK; "+std::to_string(config_.count)+" registers | CRC/layout errors "+std::to_string(errors_);pending_.clear();return;}
    if(at)pending_.erase(0,at);
}
void RtuPoller::tick(uint64_t now){if(active_&&waiting_&&now>=deadline_)stop("TIMEOUT: polling stopped; no automatic retry of ambiguous RTU response");}
